def alive(game):
    return [seat for seat in range(1, 9) if seat not in game["dead"]]

def finish(game):
    wolves = [seat for seat in alive(game) if game["roles"][str(seat)] == "狼人"]
    if not wolves:
        game["winner"] = "好人"
    elif len(wolves) >= len(alive(game)) - len(wolves):
        game["winner"] = "狼人"
    if game["winner"]:
        game["phase"] = "ended"

def run(input):
    game = json.decode(json.encode(input["game"]))
    text = input["text"].strip()
    reset = not game or "重新开始" in text or "新一局" in text
    if reset:
        # Seat 3 belongs to the user. Rotation changes assignments per game;
        # the complete role map is persisted and never given to the host model.
        seed = now_millis() % 8
        deck = ["狼人", "狼人", "预言家", "女巫", "猎人", "平民", "平民", "平民"]
        roles = {str(i + 1): deck[(i + seed) % 8] for i in range(8)}
        game = {"roles": roles, "dead": [], "day": 1, "phase": "night", "winner": "", "inspection": "", "potion_used": False, "poison_used": False, "hunter_used": False, "inspected_day": 0, "log": []}
    outcome = "第%d夜开始。你的座位是3号。" % game["day"]
    valid = True
    match = regex_find(text, ("(?:^|[^0-9])([1-8])[ ]*(?:号|座|$)", ""))
    target = int(match[1]) if match else 0
    role = game["roles"]["3"]
    spectating = 3 in game["dead"] and text in ["继续", "旁观", "继续旁观", "旁观下一轮", "继续天亮"]
    if not reset and game["phase"] == "ended":
        outcome = "%s阵营获胜。可以复盘或开始新一局。" % game["winner"]
    elif not reset and 3 in game["dead"] and not spectating:
        if role == "猎人" and not game["hunter_used"] and "开枪" in text and target in alive(game) and target != 3:
            game["dead"].append(target)
            game["hunter_used"] = True
            finish(game)
            outcome = "猎人带走%d号。" % target
        else:
            outcome = "你已经出局，可以旁观或复盘，不能继续投票或夜间行动。"
            valid = False
    elif not reset and game["phase"] == "night":
        if target and (target not in alive(game) or target == 3):
            outcome = "请选择仍存活且不是自己的座位。"
            valid = False
        elif "查验" in text:
            if role != "预言家" or not target or game.get("inspected_day", 0) == game["day"]:
                outcome = "只有预言家可以每夜查验一次有效目标。"
                valid = False
            else:
                game["inspected_day"] = game["day"]
                game["inspection"] = "%d号是%s。" % (target, "狼人" if game["roles"][str(target)] == "狼人" else "好人")
                outcome = "查验完成；结果只对你可见。"
        elif "毒" in text:
            if role != "女巫" or game["poison_used"] or not target:
                outcome = "毒药行动不合法。"
                valid = False
            else:
                game["dead"].append(target)
                game["poison_used"] = True
                finish(game)
                outcome = "毒药已使用。"
        elif ("击杀" in text or "刀" in text) and (role != "狼人" or not target or game["roles"].get(str(target)) == "狼人"):
            outcome = "只有狼人可以选择其他存活阵营的目标。"
            valid = False
        elif "救" in text and (role != "女巫" or game["potion_used"]):
            outcome = "解药行动不合法。"
            valid = False
        elif "天亮" in text or "继续" in text or "旁观" in text or "结束夜晚" in text or "击杀" in text or "刀" in text or "救" in text:
            wolves = [seat for seat in alive(game) if game["roles"][str(seat)] == "狼人"]
            victims = [seat for seat in alive(game) if game["roles"][str(seat)] != "狼人"]
            victim = target if role == "狼人" and target in victims else (victims[(game["day"] - 1) % len(victims)] if victims else 0)
            saved = role == "女巫" and "救" in text and not game["potion_used"]
            if saved:
                game["potion_used"] = True
            if victim and wolves and not saved:
                game["dead"].append(victim)
            game["phase"] = "speech"
            finish(game)
            outcome = "天亮了，%s。开始白天发言。" % ("无人出局" if saved or not victim else "%d号出局" % victim)
        else:
            outcome = "现在是夜晚，请选择符合自己身份的行动，或说继续天亮。"
    elif not reset and game["phase"] == "speech":
        if "投" in text:
            outcome = "请先完成白天发言，再进入投票。"
            valid = False
        else:
            game["phase"] = "vote"
            outcome = "你的发言已记录。其他存活角色依次发言，然后请明确投票给一个座位。"
    elif not reset and game["phase"] == "vote":
        if not spectating and (not target or target not in alive(game) or target == 3 or "投" not in text):
            outcome = "请投票给仍存活且不是自己的座位。"
            valid = False
        else:
            # NPC ballots are reproducible and exclude each voter's own seat.
            # Ties produce no exile; only the reducer tallies and advances.
            seats = alive(game)
            votes = {}
            counts = {}
            for seat in seats:
                choices = [other for other in seats if other != seat]
                votes[str(seat)] = choices[(seat + game["day"]) % len(choices)]
            if not spectating:
                votes["3"] = target
            for chosen in votes.values():
                counts[str(chosen)] = counts.get(str(chosen), 0) + 1
            peak = max(counts.values())
            winners = [int(seat) for seat in counts if counts[seat] == peak]
            exiled = winners[0] if len(winners) == 1 else 0
            if exiled:
                game["dead"].append(exiled)
            game["log"].append({"day": game["day"], "votes": votes, "exiled": exiled})
            finish(game)
            outcome = "%d号被放逐。" % exiled if exiled else "投票平票，本轮无人被放逐。"
            if not game["winner"]:
                game["day"] += 1
                game["phase"] = "night"
                outcome += "进入第%d夜。" % game["day"]
    if game["winner"]:
        outcome += "%s阵营获胜。" % game["winner"]
    public = {"day": game["day"], "phase": game["phase"], "alive": alive(game), "dead": game["dead"], "winner": game["winner"], "outcome": outcome, "votes": game["log"][-1:]}
    # Private NPC roles never enter the model prompt or extracted Memory.
    return {"game": game, "context": json.encode(public), "feedback": outcome, "valid": valid, "private": "你的身份：%s。%s" % (role, game["inspection"])}

